      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Although eligibility exclusions are listed, the retrieved evidence does not provide rationales for “notable restrictions on study eligibility” as required."
    }
  ],
  "confidence": 74
